set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000401',true);
select is(public.search_household('Archived contact')->>'total_count','0','archived records hidden by default');
select is(public.search_household('Archived contact',p_include_archived=>true)->>'total_count','1','archive toggle finds saved history');
select is(public.search_household('Hiddenchild')->>'total_count','0','archived parent hides its active children');
select is(public.search_household('Hiddenchild',p_include_archived=>true)->>'total_count','1','archive toggle includes child of archived project');
select is(public.search_household('Purchased')->>'total_count','0','purchased groceries are finished records');
select is(public.search_household('Purchased',p_include_archived=>true)->>'total_count','1','purchased grocery history remains findable');
select is(public.search_household('Completednote')->>'total_count','0','closed occurrence is hidden by default');
select is(public.search_household('Completednote',p_include_archived=>true)->>'total_count','1','completion notes are searchable in history');
select set_config('test.search_first',public.search_household('Pagination',p_page_size=>25)::text,true);
select is(current_setting('test.search_first')::jsonb->>'total_count','60','exact total is not capped to the first page');
select is(jsonb_array_length(current_setting('test.search_first')::jsonb->'results'),25,'first page is bounded');
select is(current_setting('test.search_first')::jsonb#>>'{results,0,id}','00000000-0000-4000-8000-000000050000','equal-ranked results use stable UUID ordering');
select set_config('test.search_second',public.search_household('Pagination',p_page_size=>25,p_after_score=>(current_setting('test.search_first')::jsonb#>>'{next_cursor,score}')::integer,p_after_kind=>current_setting('test.search_first')::jsonb#>>'{next_cursor,kind}',p_after_id=>(current_setting('test.search_first')::jsonb#>>'{next_cursor,id}')::uuid)::text,true);
select is(current_setting('test.search_second')::jsonb#>>'{results,0,id}','00000000-0000-4000-8000-000000050025','second page skips the exact tied boundary');
select is(current_setting('test.search_second')::jsonb->>'total_count','60','continued page retains full total');
select set_config('test.search_third',public.search_household('Pagination',p_page_size=>25,p_after_score=>(current_setting('test.search_second')::jsonb#>>'{next_cursor,score}')::integer,p_after_kind=>current_setting('test.search_second')::jsonb#>>'{next_cursor,kind}',p_after_id=>(current_setting('test.search_second')::jsonb#>>'{next_cursor,id}')::uuid)::text,true);
select is(jsonb_array_length(current_setting('test.search_third')::jsonb->'results'),10,'last page contains the remaining records');
select is(current_setting('test.search_third')::jsonb->'next_cursor','null'::jsonb,'last page has no continuation');
select is((select count(distinct item->>'id') from jsonb_array_elements((current_setting('test.search_first')::jsonb->'results')||(current_setting('test.search_second')::jsonb->'results')||(current_setting('test.search_third')::jsonb->'results')) item),60::bigint,'every paged result appears exactly once');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000402',true);
select is(public.search_household('Pagination')->>'total_count','60','partner sees the same household search');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000403',true);
select is(public.search_household('Pagination')->>'total_count','0','other household cannot search these records or their count');
select is(public.search_household('Needle')->>'total_count','16','other household searches only its own matching records');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000404',true);
select throws_ok($$select public.search_household('Needle')$$,'42501',null,'authenticated non-member denied');
reset role; set local role anon; select set_config('request.jwt.claim.sub','',true);
select throws_ok($$select public.search_household('Needle')$$,'42501',null,'anonymous search denied');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000401',true);
insert into public.decision_options(household_id,created_by,decision_id,title,notes) values
 ('00000000-0000-4000-8000-000000004001','00000000-0000-4000-8000-000000000401','00000000-0000-4000-8000-000000010018','Alpineoption','Comparisonnote'),
 ('00000000-0000-4000-8000-000000004001','00000000-0000-4000-8000-000000000401','00000000-0000-4000-8000-000000010018','Alpineoption alternative','Second note');
set local role authenticated;
select is(public.search_household('Alpineoption',array['decision'])->>'total_count','1','matching options return their parent decision once');
select is(public.search_household('Comparisonnote',array['decision'])#>>'{results,0,id}','00000000-0000-4000-8000-000000010018','option notes find their parent decision');
reset role;
update public.decision_options set archived_at=now() where title like 'Alpineoption%';
set local role authenticated;
select is(public.search_household('Alpineoption')->>'total_count','0','archived options are omitted by default');
select is(public.search_household('Alpineoption',p_include_archived=>true)->>'total_count','1','archived option text is available with the archive filter');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000403',true);
select is(public.search_household('Alpineoption',p_include_archived=>true)->>'total_count','0','option search cannot cross household boundaries');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000401',true);
-- Exercise each parent lifecycle independently on an otherwise-active document.
update public.household_documents set project_id='00000000-0000-4000-8000-000000010010' where id='00000000-0000-4000-8000-000000010019';
update public.household_projects set archived_at=now() where id='00000000-0000-4000-8000-000000010010';
set local role authenticated;
select is(public.search_household('Needle document',array['document'])->>'total_count','0','archived parent hides document');
select is(public.search_household('Needle document',array['document'],true)->>'total_count','1','history includes document with archived parent');
reset role;
update public.household_projects set archived_at=null,status='complete' where id='00000000-0000-4000-8000-000000010010';
set local role authenticated;
select is(public.search_household('Needle document',array['document'])->>'total_count','0','completed parent hides document');
select is(public.search_household('Needle document',array['document'],true)->>'total_count','1','history includes document with completed parent');
reset role;
update public.household_projects set status='cancelled' where id='00000000-0000-4000-8000-000000010010';
set local role authenticated;
select is(public.search_household('Needle document',array['document'])->>'total_count','0','cancelled parent hides document');
select is(public.search_household('Needle document',array['document'],true)->>'total_count','1','history includes document with cancelled parent');
reset role;
update public.household_projects set status='planning' where id='00000000-0000-4000-8000-000000010010';
update public.household_documents set project_id='00000000-0000-4000-8000-000000010011',booking_id='00000000-0000-4000-8000-000000010013' where id='00000000-0000-4000-8000-000000010019';
update public.trip_bookings set status='cancelled' where id='00000000-0000-4000-8000-000000010013';
set local role authenticated;
select is(public.search_household('Needle document',array['document'])->>'total_count','0','cancelled booking hides its document');
select is(public.search_household('Needle document',array['document'],true)->>'total_count','1','history includes cancelled-booking documents');
reset role;
update public.household_documents set project_id=null,booking_id=null,asset_id='00000000-0000-4000-8000-000000010015' where id='00000000-0000-4000-8000-000000010019';
update public.household_assets set archived_at=now() where id='00000000-0000-4000-8000-000000010015';
set local role authenticated;
select is(public.search_household('Needle document',array['document'])->>'total_count','0','archived inventory hides its document');
select is(public.search_household('Needle document',array['document'],true)->>'total_count','1','history includes inventory documents');
reset role;
update public.household_documents set asset_id=null,commitment_id='00000000-0000-4000-8000-000000010017' where id='00000000-0000-4000-8000-000000010019';
update public.household_commitments set status='ended' where id='00000000-0000-4000-8000-000000010017';
set local role authenticated;
select is(public.search_household('Needle document',array['document'])->>'total_count','0','ended commitments hide their documents');
select is(public.search_household('Needle document',array['document'],true)->>'total_count','1','history includes commitment documents');
reset role;
select is((select count(*)::integer from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename in('meal_definitions','areas','pets','routine_completions','expense_categories')),5,'all additional search sources publish changes');
-- More than 1 MiB of distinct option text must not form one oversized vector.
insert into public.decision_options(household_id,created_by,decision_id,title,notes)
select '00000000-0000-4000-8000-000000004001','00000000-0000-4000-8000-000000000401','00000000-0000-4000-8000-000000010018',
 'Large option '||i, (select string_agg('lex'||(i*500+j)::text,' ' order by j) from generate_series(1,400) j)
from generate_series(1,500) i;
set local role authenticated;
select is(public.search_household('lex250400',array['decision'])->>'total_count','1','an option beyond one MiB remains searchable without vector overflow');
select is(public.search_household('Large option',array['decision'])->>'total_count','1','hundreds of matching options still return one decision');
select is(public.search_household('lex250400')->>'total_count','1','large decision option sets do not break household-wide search');
reset role;
select * from finish(); rollback;
